#!/bin/bash
# scripts/gen-uprobe-offset-copy.sh — cilium/ebpf v0.22.0 の link/uprobe.go の Executable の symbol の解決 (OpenExecutable・load・lazyLoadSymbols・
# address と symbol の型) を E056 の oracle (test/oracle/cmd/uprobe-offset) に写す (E056)。address は unexported — 本文を module の source から機械的に抜き、
# internal.SafeELFFile (panic を誤りに包むだけの debug/elf.File の型) を debug/elf.File に置き換えるだけ。
#
#   scripts/gen-uprobe-offset-copy.sh            # test/oracle/cmd/uprobe-offset/cilium_copy.go を作る
#   scripts/gen-uprobe-offset-copy.sh --check    # module の source から作ったものと file が同じか (gate)
set -euo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"
MOD="$(cd "$HERE"/test/oracle && GOWORK=off GOTOOLCHAIN=local GOFLAGS=-mod=mod /usr/local/go/bin/go list -m -f '{{.Dir}}' github.com/cilium/ebpf)"
SRC="$MOD/link/uprobe.go"
OUT="$HERE/test/oracle/cmd/uprobe-offset/cilium_copy.go"
gen() {
  cat <<'H'
// Code generated by scripts/gen-uprobe-offset-copy.sh from github.com/cilium/ebpf@v0.22.0/link/uprobe.go; DO NOT EDIT.
// (Executable.address は unexported — 本文をそのまま写し、internal.SafeELFFile を debug/elf.File に置き換えた)

package main

import (
	"debug/elf"
	"errors"
	"fmt"
	"os"
	"sync"
)

H
  RE='^type (Executable|symbol) struct|^func \(s symbol\) contains\(|^func OpenExecutable\(|^func \(ex \*Executable\) (load|lazyLoadSymbols|address)\(' awk '
    BEGIN { re = ENVIRON["RE"] }
    !inb && $0 ~ re { print; if ($0 ~ /[{(]$/) { inb = 1; end = ($0 ~ /\($/) ? ")" : "}" } else print ""; next }
    inb { print; if ($0 == end) { inb = 0; print "" } }
  ' "$SRC" | sed -e 's/\*internal\.SafeELFFile/*elf.File/g' -e 's/internal\.OpenSafeELFFile/elf.Open/g'
}
if [ "${1:-}" = "--check" ]; then
  cmp -s <(gen) "$OUT" || { echo "gen-uprobe-offset-copy: $OUT が cilium の source と合わない (scripts/gen-uprobe-offset-copy.sh で作り直す)" >&2; exit 1; }
  echo "ok: cilium の uprobe の symbol の解決の写しは module の source と同じ"
else
  mkdir -p "$(dirname "$OUT")"
  gen > "$OUT"
fi
